#include <bits/stdc++.h>
using namespace std;

using l64 = long long;
using ldbl = long double;
using pii = pair<int, int>;
using pll = pair<l64, l64>;
using pdd = pair<ldbl, ldbl>;
using cpx = complex<ldbl>;

const char endline_char = '\n';
const l64 INF_VAL = 0x3f3f3f3f;
const l64 INFLL_VAL = 0x3f3f3f3f3f3f3f3f;
const l64 MODULO = 1e9+7;
const ldbl TINY = 1e-10;

mt19937_64 rnd(chrono::steady_clock::now().time_since_epoch().count());

constexpr int NUM_STEPS = 99;
constexpr int NUM_COST_STEPS = 15;

class NetworkFlow {
public:
    static constexpr int MAX_VERTICES = 50*NUM_STEPS + 2;
    static constexpr int MAX_ARCS = 2*MAX_VERTICES*NUM_COST_STEPS + MAX_VERTICES + 7;

private:
    int parent[MAX_VERTICES], head[MAX_VERTICES], next_arc[2*MAX_ARCS], to_node[2*MAX_ARCS], num_edges;
    l64 flow[2*MAX_ARCS], capacity[2*MAX_ARCS], weight[2*MAX_ARCS];
    bool visited[MAX_VERTICES];
    int que[MAX_VERTICES], in_que[MAX_VERTICES];
    l64 dist[MAX_VERTICES], potential[MAX_VERTICES];

public:
    void reset() {
        num_edges = 0;
        memset(head, -1, sizeof(head));
        memset(flow, 0, sizeof(flow));
    }

    void connect(int u, int v, l64 cap, l64 w = 0) {
        next_arc[num_edges] = head[to_node[num_edges] = u];
        head[to_node[num_edges]] = num_edges;
        capacity[num_edges] = cap;
        weight[num_edges] = w;
        ++num_edges;

        next_arc[num_edges] = head[to_node[num_edges] = v];
        head[to_node[num_edges]] = num_edges;
        capacity[num_edges] = 0;
        weight[num_edges] = -w;
        ++num_edges;
    }

    void initialize_potentials(int n) {
        memset(potential, 0, sizeof(potential));
        for (int k = 1; k < n; ++k) {
            for (int e = 0; e < num_edges; ++e) {
                if (capacity[e]) {
                    potential[to_node[e^1]] = min(potential[to_node[e^1]], potential[to_node[e]] + weight[e]);
                }
            }
        }
    }

    l64 update(int s, int t, l64& total_weight, int n) {
        memset(visited, 0, sizeof(visited));
        fill(dist, dist+n, INF_VAL);
        dist[s] = 0;
        memset(in_que, -1, sizeof(in_que));

        int qhead = 0, qtail = 0;
        in_que[que[qtail++] = s] = qtail - 1;

        while (qhead < qtail) {
            int u = que[qhead++];
            in_que[u] = -1;

            for (int e = head[u]; e != -1; e = next_arc[e]) {
                int v = to_node[e^1];
                if (flow[e] < capacity[e] && dist[v] > dist[u] + potential[u] - potential[v] + weight[e]) {
                    dist[v] = dist[u] + potential[u] - potential[v] + weight[e];
                    parent[v] = e;
                    if (in_que[v] == -1) {
                        in_que[que[qtail] = v] = qtail;
                        ++qtail;
                    }
                    for (int idx = in_que[v], prnt = (idx - 1) / 2; 
                         idx > 0 && dist[que[idx]] < dist[que[prnt]]; 
                         idx = prnt, prnt = (idx - 1) / 2) {
                        swap(que[idx], que[prnt]);
                        swap(in_que[que[idx]], in_que[que[prnt]]);
                    }
                }
            }
        }

        if (dist[t] >= INF_VAL) return 0;

        l64 df = INFLL_VAL;
        for (int e, node = t; node != s; node = to_node[e]) {
            e = parent[node];
            df = min(df, capacity[e] - flow[e]);
        }

        for (int e, node = t; node != s; node = to_node[e]) {
            e = parent[node];
            flow[e] += df;
            flow[e^1] -= df;
            total_weight += df * weight[e];
        }

        for (int i = 0; i < n; ++i) {
            potential[i] = min((l64)INF_VAL, dist[i] + potential[i]);
        }

        return df;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr); 
    cout.tie(nullptr);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int SRC = 0;
    const int DST = n*NUM_STEPS + 1;
    NetworkFlow net;
    net.reset();

    for(int i = 0; i < k; ++i) {
        int a;
        cin >> a;
        net.connect(SRC, a, 1, 0);
    }

    for(int step = 0; step < NUM_STEPS; ++step) {
        net.connect(1 + step*n, DST, INF_VAL, 0);
        if(step > 0) {
            for(int node = 1; node <= n; ++node) {
                net.connect(node + (step-1)*n, node + step*n, INF_VAL, c);
            }
        }
    }

    for(int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        for(int lvl = 0; lvl < NUM_COST_STEPS; ++lvl) {
            int edge_weight = (lvl+1)*(lvl+1) - lvl*lvl;
            for(int step = 1; step < NUM_STEPS; ++step) {
                net.connect(a + (step-1)*n, b + step*n, 1, edge_weight*d + c);
                net.connect(b + (step-1)*n, a + step*n, 1, edge_weight*d + c);
            }
        }
    }

    net.initialize_potentials(NetworkFlow::MAX_VERTICES);
    l64 cost_sum = 0;
    l64 flow_sum = 0;
    while (l64 delta = net.update(SRC, DST, cost_sum, NetworkFlow::MAX_VERTICES)) {
        flow_sum += delta;
    }

    assert(flow_sum == k);
    cout << cost_sum << endline_char;

    return 0;
}
